# Starts the DEDICATED Auth + Firestore emulators for the browser story (loopback only, ports 18765-18769, demo project).
# It uses the config and JAR copy generated by `--prepare` (review them first). Credentials are never sent.
# The emulator process id is written to <Boot>\emulators.pid; stop it with stop-emulators.ps1 (never kill by name).
# Usage: powershell -File tools/clean-env/start-emulators.ps1 -Boot <boot-dir> -Config <config-*.json> -Cache <cache-* dir>
param([Parameter(Mandatory = $true)][string]$Boot, [Parameter(Mandatory = $true)][string]$Config, [Parameter(Mandatory = $true)][string]$Cache)
$ErrorActionPreference = 'Stop'
$node = if ($env:LV_NODE24) { $env:LV_NODE24 } else { Join-Path $env:LOCALAPPDATA 'LinguistVision\tools\node-v24.13.0-win-x64\node.exe' }
$cli = Join-Path $env:APPDATA 'npm\node_modules\firebase-tools\lib\bin\firebase.js'
$java = Join-Path $env:ProgramFiles 'Java\jdk-24\bin'
$sys = $env:SystemRoot
$profile = Join-Path $Boot 'emu-profile'; $temp = Join-Path $Boot 'emu-temp'
New-Item -ItemType Directory -Force -Path $profile, $temp | Out-Null
$log = Join-Path $Boot 'emulators.log'
$psi = New-Object System.Diagnostics.ProcessStartInfo
$psi.FileName = (Join-Path $sys 'System32\cmd.exe'); $psi.WorkingDirectory = $Boot
$psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
$psi.Arguments = '/c ""' + $node + '" "' + $cli + '" emulators:start --only auth,firestore --project demo-vistavo-review-browser --config "' + $Config + '" > "' + $log + '" 2>&1"'
$psi.EnvironmentVariables.Clear()
$vars = @{
  SystemRoot = $sys; WINDIR = $sys; PATH = ($java + ';' + (Join-Path $sys 'System32'))
  USERPROFILE = $profile; APPDATA = $profile; LOCALAPPDATA = $profile; HOME = $profile
  TEMP = $temp; TMP = $temp
  FIREBASE_EMULATORS_PATH = $Cache; FIREBASE_CLI_DISABLE_UPDATE_CHECK = 'true'; CI = 'true'
}
foreach ($k in $vars.Keys) { $psi.EnvironmentVariables[$k] = $vars[$k] }
$p = [System.Diagnostics.Process]::Start($psi)
$p.Id | Set-Content (Join-Path $Boot 'emulators.pid') -Encoding ascii
"started emulator launcher pid $($p.Id); log: $log"
